package org.firstinspires.ftc.teamcode.subsystems;

import org.firstinspires.ftc.teamcode.config.MatchState;

import java.util.Locale;

// Generated by refract-suite ftc-construct. The turret zero for an OpMode that is not run after an auto (TeleOp
// practice, the shot tuners). The yaw angle is counted from the encoder, and the zero only lives as long as the
// power: after a battery change or a restart the turrets may have been turned, so the zero is never taken by itself.
// Two ways to set it:
//   homing  options (YawHoming, no extra hardware, once program 3 measured the stops): in INIT it arms homing, which
//           starts at START; after START a press starts it at once. The turret finds its zero from its end stops
//           while the robot can already drive.
//   by hand both turrets straight forward, cross in INIT (the fallback when homing is not set up or failed)
// Until it is zeroed the turret stays off. MatchState.yawZeroed carries the zero between OpModes of one power-up.
public final class TurretZero {
    private final Yaw yaw;
    private boolean needed;
    private boolean zeroed, armed, finishedNow;
    private YawHoming homing;
    private String failure = "";
    private long finishedAtNs = 0;

    public TurretZero(Yaw yaw) {
        this.yaw = yaw;
        needed = !MatchState.yawZeroed;
    }

    // every INIT loop; cross = both turrets point straight forward now (by hand)
    public void init(boolean crossPressed) {
        if (homing != null && homing.active()) return;
        if (!needed && !zeroed) return;
        if (yaw.hasIndex()) {
            zeroed = yaw.indexZero();
        } else if (crossPressed) {
            yaw.zero();
            zeroed = true;
            armed = false;
            failure = "";
        }
    }

    // options in INIT: home at START (the turret may not move before it)
    public boolean arm() {
        if (!YawHoming.available()) return false;
        armed = true;
        return true;
    }

    public boolean armed() {
        return armed;
    }

    // START: an armed homing begins
    public void start() {
        if (armed) {
            armed = false;
            startHoming();
        } else if (needed && zeroed) {
            MatchState.yawZeroed = true;
        }
    }

    // a press of options after START (or an armed start): home now, whether or not it was zeroed
    public boolean startHoming() {
        if (!YawHoming.available() || (homing != null && homing.active())) return false;
        homing = new YawHoming(yaw, MatchState.yawZeroed);
        homing.start();
        failure = "";
        return true;
    }

    // every run loop: drives the homing, if there is one
    public void update() {
        if (homing == null || !homing.active()) return;
        homing.update();
        if (homing.finished()) {
            zeroed = true;
            needed = true;
            MatchState.yawZeroed = true;
            finishedNow = true;
            finishedAtNs = System.nanoTime();
        } else if (homing.failed()) {
            // the old zero may be gone (the first stop already moved it): back to the by-hand zero
            zeroed = false;
            needed = true;
            MatchState.yawZeroed = false;
            failure = homing.message();
        }
    }

    // true once, the loop after homing finished (for a rumble)
    public boolean finishedJustNow() {
        boolean f = finishedNow;
        finishedNow = false;
        return f;
    }

    // homing finished a moment ago: the screen keeps saying how long it took for a few seconds
    public boolean justHomed() {
        return finishedAtNs != 0 && (System.nanoTime() - finishedAtNs) / 1e9 < 6;
    }

    // the TeleOp run screen shows the status line while it matters
    public boolean showStatus() {
        return homing() || !done() || justHomed();
    }

    public boolean homing() {
        return homing != null && homing.active();
    }

    // STOP in the middle of homing
    public void stop() {
        if (homing != null) homing.abort();
    }

    public boolean done() {
        return (!needed || zeroed) && !homing();
    }

    // armed counts as ready to start (the zero comes right after START)
    public boolean readyToStart() {
        return done() || armed;
    }

    public String status() {
        if (homing()) return homing.status();
        if (!failure.isEmpty()) {
            return "TURRET HOMING FAILED: " + failure + ". STOP, turn BOTH turrets straight forward by hand, INIT, press cross.";
        }
        if (armed) return "Turret: will HOME at START (options pressed). The robot can drive while it does.";
        if (homing != null && homing.finished() && done() && justHomed()) return homing.status();
        if (!needed) return "Turret zero: kept from earlier (an auto or an earlier program). Hold options 1.5 s to home it again.";
        if (yaw.hasIndex()) {
            return zeroed ? String.format(Locale.US, "Turret zero: INDEXED (from the index switch), front turret at %.1f deg", yaw.frontDeg())
                    : "Turret zero: turn the turrets slowly LEFT through forward until this says INDEXED"
                    + (yaw.indexTooFast() ? " (too fast: back right past it, then slower)" : "");
        }
        if (zeroed) return "Turret zero: SET (both turrets were straight forward)";
        if (YawHoming.available()) {
            return "TURRET NOT ZEROED: press options (in the start corner) to home it at START, or turn BOTH turrets straight forward and press cross. Until then the turret is off.";
        }
        return "TURRET NOT ZEROED: turn BOTH turrets straight forward by hand, then press cross. Until then the turret is off.";
    }
}
